use serde_json::{Value, from_str};

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    if let Ok(num) = from_str::<f64>(&input.to_string()) {
        if num >= -1000000.0 && num <= 1000000.0 {
            let cents = (num * 100.0).round() as i64;
            serde_json::Value::Number(cents.into())
        } else {
            serde_json::Value::Null
        }
    } else {
        serde_json::Value::Null
    }
}
